#include "app/fonts.hpp"

#include <imgui.h>

#include <cstdio>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iterator>

#include "core/font_check.hpp"
#include "core/i18n.hpp"
#include "io/path_utf8.hpp"

// Generated by CMake from third_party/fonts/*.ttf (see the embed step in CMakeLists.txt).
extern const unsigned char kInterFontData[];
extern const unsigned long long kInterFontSize;
extern const unsigned char kMonoFontData[];
extern const unsigned long long kMonoFontSize;

namespace trace {

namespace {

constexpr std::uintmax_t kMaxFontFileBytes = 32u * 1024u * 1024u;
constexpr std::size_t kMinFontFileBytes = 256;

void setName(ImFontConfig& config, const char* name) {
    std::snprintf(config.Name, sizeof(config.Name), "%s", name);
}

// Text is sharpest when every glyph lands on a whole pixel and is not oversampled (oversampling and
// fractional positions both blur it through the texture filter). Sizes are kept whole as well, see theme.cpp.
ImFontConfig crispConfig() {
    ImFontConfig config;
    config.OversampleH = 1;
    config.OversampleV = 1;
    config.PixelSnapH = true;
    return config;
}

} // namespace

void Fonts::init() {
    ImGuiIO& io = ImGui::GetIO();

    // The scalable variant of ImGui's default font: the bitmap one is only clean at exactly 13 px.
    ImFontConfig classic = crispConfig();
    setName(classic, "Classic");
    classic_ = io.Fonts->AddFontDefaultVector(&classic);

    ImFontConfig builtIn = crispConfig();
    builtIn.FontDataOwnedByAtlas = false; // the data lives in the executable
    setName(builtIn, "Inter");
    inter_ = io.Fonts->AddFontFromMemoryTTF(const_cast<unsigned char*>(kInterFontData),
                                            static_cast<int>(kInterFontSize), 0.0f, &builtIn);
    setName(builtIn, "JetBrains Mono");
    mono_ = io.Fonts->AddFontFromMemoryTTF(const_cast<unsigned char*>(kMonoFontData),
                                           static_cast<int>(kMonoFontSize), 0.0f, &builtIn);
    io.FontDefault = classic_;
}

std::string Fonts::readFontFile(const std::string& pathUtf8, std::vector<std::uint8_t>& data) {
    namespace fs = std::filesystem;
    const fs::path path = pathFromUtf8(pathUtf8);
    std::error_code ec;
    const std::uintmax_t size = fs::file_size(path, ec);
    if (ec)
        return tr(Str::ErrFontRead);
    if (size > kMaxFontFileBytes)
        return tr(Str::ErrFontTooLarge);
    if (size < kMinFontFileBytes)
        return tr(Str::ErrFontTooSmall);

    std::ifstream in(path, std::ios::binary);
    if (!in)
        return tr(Str::ErrFontRead);
    data.assign(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
    if (!looksLikeFont(data)) {
        data.clear();
        return tr(Str::ErrFontInvalid);
    }
    return {};
}

void Fonts::apply(FontChoice choice, const std::string& customPath, std::string& error, FontChoice& usedChoice) {
    ImGuiIO& io = ImGui::GetIO();
    usedChoice = choice;

    // Load, replace or drop the custom font when its path changed.
    if (customPath != customPath_ || (choice == FontChoice::Custom && !custom_ && !customPath.empty())) {
        if (custom_) {
            io.Fonts->RemoveFont(custom_);
            custom_ = nullptr;
        }
        customData_.clear();
        customName_.clear();
        customPath_ = customPath;

        if (!customPath.empty() && choice == FontChoice::Custom) {
            std::vector<std::uint8_t> data;
            error = readFontFile(customPath, data);
            if (error.empty()) {
                customData_ = std::move(data);
                ImFontConfig config = crispConfig();
                config.FontDataOwnedByAtlas = false;
                setName(config, "Custom");
                custom_ = io.Fonts->AddFontFromMemoryTTF(customData_.data(), static_cast<int>(customData_.size()), 0.0f,
                                                         &config);
                if (!custom_) {
                    customData_.clear();
                    error = tr(Str::ErrFontLoad);
                }
            }
            if (custom_)
                customName_ = utf8FromPath(pathFromUtf8(customPath).filename());
            else
                customPath_.clear(); // do not retry the same broken file every frame
        }
    }

    ImFont* font = classic_;
    switch (choice) {
    case FontChoice::Classic:
        font = classic_;
        break;
    case FontChoice::Inter:
        font = inter_;
        break;
    case FontChoice::Mono:
        font = mono_;
        break;
    case FontChoice::Custom:
        if (custom_) {
            font = custom_;
        } else {
            font = inter_ ? inter_ : classic_;
            usedChoice = FontChoice::Inter;
        }
        break;
    }
    io.FontDefault = font ? font : classic_;
}

} // namespace trace
